get_ipython().run_cell_magic('writefile', f'{STAGING}/e7_models.py', '"""E7 identity-only additive, shared bilinear-interaction and nonlinear models."""\nimport json\nimport time\nfrom pathlib import Path\nimport numpy as np\nfrom scipy.optimize import minimize\n\n\ndef require(value, message):\n    if not bool(value):raise ValueError(message)\n\n\ndef progress(text):\n    print(time.strftime(\'%H:%M:%S\'), text, flush=True)\n\n\ndef reverse(pair):\n    return \'__\'.join(reversed(pair.split(\'__\')))\n\n\ndef canonical(value):\n    import hashlib\n    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(\',\', \':\')).encode()).hexdigest()\n\n\ndef sha_file(path):\n    import hashlib\n    h = hashlib.sha256()\n    with Path(path).open(\'rb\') as stream:\n        for chunk in iter(lambda: stream.read(1024*1024), b\'\'):h.update(chunk)\n    return h.hexdigest()\n\n\ndef atomic_json(path, value):\n    path = Path(path);path.parent.mkdir(parents=True, exist_ok=True)\n    tmp = path.with_suffix(path.suffix+\'.tmp\')\n    tmp.write_text(json.dumps(value, indent=2, allow_nan=False)+\'\\n\', encoding=\'utf-8\');tmp.replace(path)\n\n\ndef atomic_csv(path, value):\n    path = Path(path);path.parent.mkdir(parents=True, exist_ok=True)\n    tmp = path.with_suffix(path.suffix+\'.tmp\')\n    value.to_csv(tmp, index=False);tmp.replace(path)\n\n\ndef freeze(path, value):\n    if Path(path).is_file():require(json.loads(Path(path).read_text()) == value, \'Changed frozen settings: \'+str(path))\n    else:atomic_json(path, value)\n\n\ndef geometry(pairs, languages):\n    n = len(languages)\n    source = np.array([languages.index(pair.split(\'__\')[0]) for pair in pairs])\n    target = np.array([languages.index(pair.split(\'__\')[1]) for pair in pairs])\n    x = np.column_stack([np.ones(len(pairs))]+\n        [(source == j).astype(float)-(source == n-1).astype(float) for j in range(n-1)]+\n        [(target == j).astype(float)-(target == n-1).astype(float) for j in range(n-1)])\n    features = np.column_stack([np.eye(n)[source], np.eye(n)[target]])\n    return {\'pairs\': pairs, \'languages\': languages, \'X\': x, \'features\': features, \'source\': source, \'target\': target}\n\n\ndef folds(geo, seed=20261117, n_inner=5):\n    x, pairs = geo[\'X\'], geo[\'pairs\']\n    dyads = [p for p in pairs if p < reverse(p)]\n    require(len(dyads) == 20 and len(pairs) == 40, \'Expected original 20 reciprocal dyads\')\n    result, audit = [], []\n    for j, outer in enumerate(dyads):\n        test = [pairs.index(outer), pairs.index(reverse(outer))]\n        train = [i for i in range(len(pairs)) if i not in test]\n        require(np.linalg.matrix_rank(x[train]) == x.shape[1], \'Outer additive model unidentified\')\n        valid = []\n        for inner in dyads:\n            if inner == outer:continue\n            validation = [pairs.index(inner), pairs.index(reverse(inner))]\n            fit = [i for i in train if i not in validation]\n            rank = int(np.linalg.matrix_rank(x[fit]))\n            okay = rank == x.shape[1]\n            audit.append({\'outer\': outer, \'inner\': inner, \'inner_rank\': rank,\n                          \'expected_rank\': x.shape[1], \'valid\': okay, \'selected\': False})\n            if okay:valid.append({\'dyad\': inner, \'train\': fit, \'validation\': validation})\n        require(len(valid) >= n_inner, \'Too few topology-valid inner folds; do not silently change design\')\n        selected = np.random.default_rng(seed+j).choice(len(valid), n_inner, replace=False)\n        chosen = sorted([valid[int(i)] for i in selected], key=lambda v: v[\'dyad\'])\n        for row in audit:\n            if row[\'outer\'] == outer:row[\'selected\'] = row[\'inner\'] in {v[\'dyad\'] for v in chosen}\n        result.append({\'dyad\': outer, \'train\': train, \'test\': test, \'inner\': chosen})\n    return result, audit\n\n\ndef grid(model, config):\n    size_name = \'rank\' if model == \'M2_bilinear\' else \'hidden\'\n    sizes = config[\'ranks\'] if model == \'M2_bilinear\' else config[\'hidden\']\n    # The tie rule prefers stronger regularization and then smaller capacity.\n    return [{size_name: size, \'penalty\': penalty} for penalty in sorted(config[\'penalties\'], reverse=True)\n            for size in sorted(sizes)]\n\n\ndef training_context(geo, allowed, mean):\n    allowed = np.asarray(allowed, int)\n    x = geo[\'X\'][allowed]\n    require(np.linalg.matrix_rank(x) == x.shape[1], \'Training additive design unidentified\')\n    values = np.asarray(mean)[allowed]\n    require(np.isfinite(values).all(), \'Nonfinite training values\')\n    center = float(values.mean());scale = float(values.std())\n    scale = max(scale, 1e-12)\n    z = (values-center)/scale\n    inverse = np.linalg.pinv(x)\n    residualizer = np.eye(len(allowed))-x@inverse\n    residualizer = (residualizer+residualizer.T)/2\n    return {\'allowed\': allowed, \'X\': x, \'inverse\': inverse, \'R\': residualizer,\n            \'z\': z, \'center\': center, \'scale\': scale}\n\n\ndef objective(parameters, model, hp, geo, ctx):\n    """Variable-projection OLS: source/target effects are unpenalized in every model."""\n    allowed = ctx[\'allowed\'];n = len(geo[\'languages\']);penalty = hp[\'penalty\']\n    if model == \'M2_bilinear\':\n        rank = hp[\'rank\']\n        raw_u = parameters[:n*rank].reshape(n, rank)\n        raw_v = parameters[n*rank:].reshape(n, rank)\n        u = raw_u-raw_u.mean(0, keepdims=True);v = raw_v-raw_v.mean(0, keepdims=True)\n        s, t = geo[\'source\'][allowed], geo[\'target\'][allowed]\n        h = np.sum(u[s]*v[t], axis=1)\n        residual = ctx[\'R\']@(h-ctx[\'z\'])\n        g = ctx[\'R\']@residual/len(allowed)\n        gu, gv = penalty*u, penalty*v\n        np.add.at(gu, s, g[:, None]*v[t]);np.add.at(gv, t, g[:, None]*u[s])\n        gu -= gu.mean(0, keepdims=True);gv -= gv.mean(0, keepdims=True)\n        value = residual@residual/(2*len(allowed))+penalty*(np.sum(u*u)+np.sum(v*v))/2\n        return float(value), np.r_[gu.ravel(), gv.ravel()]\n    hidden = hp[\'hidden\'];p = geo[\'features\'].shape[1]\n    w = parameters[:p*hidden].reshape(p, hidden)\n    bias = parameters[p*hidden:p*hidden+hidden]\n    v = parameters[p*hidden+hidden:]\n    features = geo[\'features\'][allowed]\n    activation = np.tanh(features@w+bias)\n    h = activation@v\n    residual = ctx[\'R\']@(h-ctx[\'z\']);g = ctx[\'R\']@residual/len(allowed)\n    delta = g[:, None]*v[None]*(1-activation*activation)\n    gradient = np.r_[(features.T@delta+penalty*w).ravel(), delta.sum(0)+penalty*bias,\n                      activation.T@g+penalty*v]\n    value = residual@residual/(2*len(allowed))+penalty*np.dot(parameters, parameters)/2\n    return float(value), gradient\n\n\ndef interaction(parameters, model, hp, geo):\n    n = len(geo[\'languages\'])\n    if model == \'M2_bilinear\':\n        rank = hp[\'rank\'];u = parameters[:n*rank].reshape(n, rank);v = parameters[n*rank:].reshape(n, rank)\n        u = u-u.mean(0, keepdims=True);v = v-v.mean(0, keepdims=True)\n        return np.sum(u[geo[\'source\']]*v[geo[\'target\']], axis=1)\n    hidden = hp[\'hidden\'];p = geo[\'features\'].shape[1]\n    w = parameters[:p*hidden].reshape(p, hidden);b = parameters[p*hidden:p*hidden+hidden]\n    v = parameters[p*hidden+hidden:]\n    return np.tanh(geo[\'features\']@w+b)@v\n\n\ndef fit(geo, allowed, mean, model, hp, config):\n    ctx = training_context(geo, allowed, mean)\n    base_coef = ctx[\'inverse\']@ctx[\'z\']\n    base_prediction = ctx[\'center\']+ctx[\'scale\']*(geo[\'X\']@base_coef)\n    if model == \'M1_additive\':\n        return base_prediction, {\'model\': model, \'active_nonlinearity\': False, \'parameters\': len(base_coef),\n                                 \'nominal_parameters\': len(base_coef),\n                                 \'selected_start\': \'OLS\', \'converged\': True, \'objective\': float(np.mean((ctx[\'R\']@ctx[\'z\'])**2)/2),\n                                 \'gradient_inf\': 0., \'iterations\': 0, \'start_audit\': [],\n                                 \'main_coefficients_standardized\': base_coef.tolist(),\n                                 \'response_center\': ctx[\'center\'], \'response_scale\': ctx[\'scale\']}\n    n = len(geo[\'languages\'])\n    count = 2*n*hp[\'rank\'] if model == \'M2_bilinear\' else (geo[\'features\'].shape[1]+2)*hp[\'hidden\']\n    zero = np.zeros(count)\n    best_value = objective(zero, model, hp, geo, ctx)[0]\n    best = zero;selected = \'zero\';converged = True;iterations = 0;gradient_inf = 0.\n    starts = []\n    for seed in config[\'initialization_seeds\']:\n        rng = np.random.default_rng(seed)\n        scale = .12 if model == \'M2_bilinear\' else .4\n        initial = rng.normal(0, scale, count)\n        result = minimize(objective, initial, args=(model, hp, geo, ctx), jac=True, method=\'L-BFGS-B\',\n                          options={\'maxiter\': config[\'maxiter\'], \'ftol\': 1e-12, \'gtol\': 1e-7, \'maxls\': 30})\n        finite = bool(np.isfinite(result.fun) and np.isfinite(result.x).all() and np.isfinite(result.jac).all())\n        norm = float(np.max(np.abs(result.jac))) if finite else None\n        starts.append({\'seed\': seed, \'success\': bool(result.success), \'finite\': finite,\n                       \'iterations\': int(result.nit), \'objective\': float(result.fun) if finite else None,\n                       \'gradient_inf\': norm, \'message\': str(result.message)})\n        if finite and result.fun < best_value-1e-10:\n            best_value = float(result.fun);best = result.x;selected = str(seed)\n            converged = bool(result.success);iterations = int(result.nit);gradient_inf = norm\n    h = interaction(best, model, hp, geo)\n    coefficient = ctx[\'inverse\']@(ctx[\'z\']-h[ctx[\'allowed\']])\n    prediction = ctx[\'center\']+ctx[\'scale\']*(geo[\'X\']@coefficient+h)\n    require(np.isfinite(prediction).all(), \'Nonfinite nonlinear predictions; no row omission\')\n    active = selected != \'zero\'\n    return prediction, {\'model\': model, \'hyperparameters\': hp, \'active_nonlinearity\': active,\n        \'parameters\': int(geo[\'X\'].shape[1]+count) if active else int(geo[\'X\'].shape[1]),\n        \'nominal_parameters\': int(geo[\'X\'].shape[1]+count), \'selected_start\': selected,\n        \'converged\': converged, \'objective\': best_value, \'gradient_inf\': gradient_inf,\n        \'iterations\': iterations, \'start_audit\': starts,\n        \'main_coefficients_standardized\': coefficient.tolist(), \'interaction_parameters\': best.tolist(),\n        \'response_center\': ctx[\'center\'], \'response_scale\': ctx[\'scale\'],\n        \'failed_starts\': sum(not row[\'success\'] for row in starts),\n        \'parameter_count_note\': \'nominal allocated coefficients, not effective degrees of freedom; bilinear centering/gauge redundancies remain\',\n        \'prediction_outside_unit_interval\': int(((prediction < 0)|(prediction > 1)).sum())}\n\n\ndef fit_outer(geo, fold, training_means, validation_means, config):\n    """Outer dyad excluded from fitting AND all validation/hyperparameter selection."""\n    predictions, selected, validation_rows, optimizer_rows = {}, [], [], []\n    m1, meta = fit(geo, fold[\'train\'], training_means, \'M1_additive\', {}, config)\n    predictions[\'M1_additive\'] = m1\n    selected.append({\'model\': \'M1_additive\', **meta})\n    for model in [\'M2_bilinear\', \'M3_tanh\']:\n        candidates = []\n        for grid_index, hp in enumerate(grid(model, config), 1):\n            errors = []\n            for inner in fold[\'inner\']:\n                prediction, status = fit(geo, inner[\'train\'], training_means, model, hp, config)\n                validation = np.asarray(inner[\'validation\'], int)\n                error = float(np.mean((prediction[validation]-validation_means[validation])**2))\n                errors.append(error)\n                validation_rows.append({\'model\': model, \'hyperparameters\': hp, \'inner_dyad\': inner[\'dyad\'],\n                                        \'validation_direction_MSE\': error, \'converged\': status[\'converged\'],\n                                        \'active_nonlinearity\': status[\'active_nonlinearity\']})\n                optimizer_rows.extend({\'phase\': \'inner\', \'model\': model, \'hyperparameters\': hp,\n                                       \'inner_dyad\': inner[\'dyad\'], **row} for row in status[\'start_audit\'])\n            candidates.append((float(np.mean(errors)), hp))\n            if config.get(\'verbose\', True):\n                progress(f\'{model}: validation grid {grid_index}/{len(grid(model, config))} complete\')\n        # Grid order already defines strong-penalty/small-capacity tie breaking.\n        best_score = min(score for score, _ in candidates)\n        chosen = next(hp for score, hp in candidates if score <= best_score+1e-12)\n        prediction, status = fit(geo, fold[\'train\'], training_means, model, chosen, config)\n        predictions[model] = prediction\n        selected.append({**status, \'validation_direction_MSE\': best_score})\n        optimizer_rows.extend({\'phase\': \'outer\', \'model\': model, \'hyperparameters\': chosen, \'inner_dyad\': \'\', **row}\n                              for row in status[\'start_audit\'])\n    return predictions, selected, validation_rows, optimizer_rows\n')


