get_ipython().run_cell_magic('writefile', f'{STAGING}/e7_uncertainty.py', '"""E6 R2 audit: preserve original intervals; diagnose bias without forcing containment."""\nimport numpy as np\nimport pandas as pd\nfrom scipy.stats import norm\nfrom e7_models import require\n\n\ndef prediction_scores(y, prediction, weights, direction_weights=None):\n    weights = weights/weights.sum(1, keepdims=True)\n    d = y.shape[1]\n    if direction_weights is None:direction_weights = np.ones((len(weights), d))\n    direction_weights = direction_weights/direction_weights.sum(1, keepdims=True)\n    mean = weights@y;second = weights@(y*y)\n    row_mse = np.sum(direction_weights*(second-2*mean*prediction+prediction*prediction), axis=1)\n    grand = np.sum(direction_weights*mean, axis=1)\n    row_var = np.sum(direction_weights*second, axis=1)-grand*grand\n    dir_mse = np.sum(direction_weights*(mean-prediction)**2, axis=1)\n    dir_var = np.sum(direction_weights*(mean-grand[:, None])**2, axis=1)\n    divide = lambda a,b: np.divide(a, b, out=np.full(np.shape(a), np.nan), where=b > 1e-20)\n    return np.column_stack([1-divide(row_mse, row_var), 1-divide(dir_mse, dir_var),\n        np.sum(direction_weights*(weights@np.abs(y-prediction)), axis=1), np.sqrt(np.maximum(row_mse, 0)),\n        np.sum(direction_weights*np.abs(mean-prediction), axis=1), np.sqrt(dir_mse), dir_mse])\n\n\nMETRICS = [\'row_R2\', \'direction_R2\', \'row_MAE\', \'row_RMSE\', \'direction_MAE\', \'direction_RMSE\', \'direction_MSE\']\n\n\ndef bca(point, draws, jackknife):\n    samples = np.asarray(draws);samples = samples[np.isfinite(samples)]\n    jack = np.asarray(jackknife);jack = jack[np.isfinite(jack)]\n    if len(samples) < 100 or len(jack) < 3:return (np.nan, np.nan, np.nan, np.nan, True)\n    probability = (np.sum(samples < point)+.5*np.sum(samples == point))/len(samples)\n    # Finite Monte Carlo continuity bounds are explicit diagnostics, not CI clipping.\n    clipped = float(np.clip(probability, .5/len(samples), 1-.5/len(samples)))\n    z0 = norm.ppf(clipped)\n    influence = jack.mean()-jack\n    denominator = 6*np.sum(influence*influence)**1.5\n    acceleration = np.sum(influence**3)/denominator if denominator > 1e-30 else 0.\n    z = norm.ppf([.025, .975]);den = 1-acceleration*(z0+z)\n    if np.any(den <= 0):return (np.nan, np.nan, float(z0), float(acceleration), True)\n    levels = norm.cdf(z0+(z0+z)/den)\n    low, high = np.quantile(samples, levels)\n    minimum_tail_draws = min(levels[0], 1-levels[1])*len(samples)\n    unstable = bool(minimum_tail_draws < 20 or probability != clipped)\n    return float(low), float(high), float(z0), float(acceleration), unstable\n\n\ndef audit_e6(frames, ids, pairs, predictions, e6_root, outcome, output):\n    """Same diagnostics for all6 panels, not only the flagged NLLB interval."""\n    from pathlib import Path\n    from e7_models import atomic_csv, progress\n    root = Path(e6_root)/\'analysis\'\n    with np.load(root/(outcome+\'_bootstrap.npz\'), allow_pickle=False) as z:\n        labels = z[\'prediction_axes\'].tolist();metrics = z[\'prediction_metrics\'].tolist();samples = z[\'prediction\']\n    old_stats = pd.read_csv(root/\'E6_regime_statistics.csv\')\n    rows = []\n    for key, frame in frames.items():\n        model = key[0]+\'__\'+key[1]+\'__both\'\n        require(model in labels, \'Missing original E6 bootstrap series\')\n        y = frame.pivot(index=\'sentence_id\', columns=\'pair\', values=outcome).loc[ids, pairs].to_numpy(float)\n        prediction = predictions[(key[0], key[1], outcome)]\n        point = prediction_scores(y, prediction, np.ones((1, len(ids))))[0]\n        jacks = np.stack([prediction_scores(np.delete(y, i, 0), prediction,\n                                          np.ones((1, len(ids)-1)))[0] for i in range(len(ids))])\n        for metric in [\'row_R2\', \'direction_R2\', \'direction_MAE\', \'direction_RMSE\']:\n            j = METRICS.index(metric);draw = samples[:, labels.index(model), metrics.index(metric)]\n            finite = draw[np.isfinite(draw)]\n            lo, hi = np.quantile(finite, [.025, .975])\n            blo, bhi, z0, acceleration, unstable = bca(point[j], draw, jacks[:, j])\n            old = old_stats[(old_stats.study == key[0]) & (old_stats.regime == key[1]) &\n                (old_stats.outcome == outcome) & (old_stats.analysis == \'strict_unseen_meanings_and_dyad\') &\n                (old_stats.model == \'both\') & (old_stats.metric == metric)]\n            require(len(old) == 1 and abs(float(old.estimate.iloc[0])-point[j]) < 1e-10, \'E6 point does not reproduce\')\n            require(np.allclose([lo, hi], old[[\'ci_low\', \'ci_high\']].to_numpy()[0], atol=1e-10, rtol=0), \'E6 bootstrap CI does not reproduce\')\n            rows.append({\'study\': key[0], \'regime\': key[1], \'outcome\': outcome, \'metric\': metric,\n                \'point\': point[j], \'original_percentile_low\': lo, \'original_percentile_high\': hi,\n                \'point_outside_original_CI\': bool(point[j] < lo or point[j] > hi),\n                \'bootstrap_mean_minus_point\': float(finite.mean()-point[j]),\n                \'bootstrap_fraction_below_point\': float(np.mean(finite < point[j])),\n                \'basic_low_diagnostic\': 2*point[j]-hi, \'basic_high_diagnostic\': 2*point[j]-lo,\n                \'basic_upper_above_one_for_R2\': bool(metric.endswith(\'R2\') and 2*point[j]-lo > 1),\n                \'BCa_low_diagnostic\': blo, \'BCa_high_diagnostic\': bhi, \'BCa_z0\': z0,\n                \'BCa_acceleration\': acceleration, \'BCa_insufficient_tail_draws\': unstable,\n                \'jackknife_bias_estimate\': float((len(ids)-1)*(jacks[:, j].mean()-point[j])),\n                \'jackknife_SE\': float(np.sqrt((len(ids)-1)/len(ids)*np.sum((jacks[:, j]-jacks[:, j].mean())**2))),\n                \'interpretation\': \'diagnostic comparisons, not automatic replacements; percentile CIs need not contain \'\n                    \'the point. Do not force containment or clip endpoints. Prefer MAE/RMSE uncertainty if R2 \'\n                    \'bootstrap bias/tail support prevents a stable interval; old E6 files unchanged.\'})\n        progress(\'E6 uncertainty audit: \'+model+\' \'+outcome)\n    table = pd.DataFrame(rows)\n    atomic_csv(Path(output)/(\'E6_uncertainty_audit_\'+outcome+\'.csv\'), table)\n    return table\n')


